async fn ignores_deferred_provider_cancellation_failure(){let(lane,drive,faux)=fixture().await;faux.set_responses(vec![answer().into()]);submit_deferred(&lane,&drive).await;cancel_projection(&lane).await;lane.cancel_fails.store(true,std::sync::atomic::Ordering::SeqCst);let outcome=drive_operation(lane.as_ref(),&drive).await.expect("reconcile remote failure");assert!(matches!(outcome,maho_agent::harness::agent_harness::DriveOutcome::Settled {..}));assert!(lane.state().operation.is_none());{let options=lane.cancel_options.lock().expect("cancel options");assert_eq!(options.len(),1);assert!(!options[0].signal.as_ref().expect("cleanup signal").aborted());assert!(drive.gate.signal().aborted());}assert_eq!(lane.state(),restore_lane(&lane.session,"main",&BACKGROUND_CONTEXT).await.expect("restore cancelled lane"));}
#[tokio::test]
async fn cancelled_effect_can_resume_between_response_and_terminal_cleanup(){let(lane,drive,faux)=fixture().await;faux.set_responses(vec![answer().into()]);submit_deferred(&lane,&drive).await;let pending=unknown_poll(&lane).await;let OperationState::DeferredEffectPending(p)=pending else {unreachable!()};lane.session.delete_list(&pending_assistant_frames("op",&p.response_entry_id),&BACKGROUND_CONTEXT).await.expect("remove malformed test frame");cancel_projection(&lane).await;assert_eq!(maho_agent::harness::runtime::drive::reconcile::reconcile_operation(lane.as_ref(),&drive).await.expect("settle cancelled effect"),ProcedureResult::Continue);assert!(matches!(current(&lane),OperationState::Checkpoint(_)));let entry=lane.session.get_entry(&p.response_entry_id,&BACKGROUND_CONTEXT).await.expect("response entry").expect("committed response");let Some(maho_ai::types::Message::Assistant(message))=entry.kind.message().and_then(|m|m.try_as_llm()) else {panic!("not assistant")};assert_eq!(message.stop_reason,maho_ai::types::StopReason::Aborted);assert!(lane.session.get_value(&operation_result("op"),&BACKGROUND_CONTEXT).await.expect("no result yet").is_none());let resumed=poll_drive();let result=drive_operation(lane.as_ref(),&resumed).await.expect("resume cleanup");let maho_agent::harness::agent_harness::DriveOutcome::Settled {outcome}=result else {panic!("not settled")};assert_eq!(outcome.status,TerminalStatus::Aborted);assert!(lane.state().operation.is_none());}
#[tokio::test]
async fn deferred_poll_declines_intent_when_cancellation_wins_hook(){let(lane,drive,faux)=fixture().await;faux.set_responses(vec![answer().into()]);submit_deferred(&lane,&drive).await;let started=Arc::new(tokio::sync::Notify::new());let release=Arc::new(tokio::sync::Notify::new());let begun=started.clone();let unblock=release.clone();let _registration=lane.hooks.on(maho_agent::harness::hooks::HookName::BeforeRequest,Arc::new(move |_,_|{let begun=begun.clone();let unblock=unblock.clone();Box::pin(async move {let released=unblock.notified();tokio::pin!(released);released.as_mut().enable();begun.notify_one();released.await;Ok(maho_agent::harness::hooks::HookResult::None)})}),None);let poll=Arc::new(poll_drive());let polling={let lane=lane.clone();let poll=poll.clone();tokio::spawn(async move {maho_agent::harness::runtime::drive::deferred::run_deferred(lane.as_ref(),&poll,&current(&lane)).await})};tokio::time::timeout(std::time::Duration::from_secs(5),started.notified()).await.expect("hook start signal");cancel_projection(&lane).await;release.notify_one();assert_eq!(tokio::time::timeout(std::time::Duration::from_secs(5),polling).await.expect("poll finish signal").expect("poll task").expect("cancelled poll"),ProcedureResult::Continue);assert_eq!(faux.state().deferred_fetch_count,0);assert_eq!(*poll.deferred_permits.lock().expect("permit lock"),1);let OperationState::DeferredSuspended(s)=current(&lane) else {panic!("not suspended")};assert_eq!(s.deferred.operation.control,Control::CancelRequested {requested_at:10});assert_eq!(lane.state(),restore_lane(&lane.session,"main",&BACKGROUND_CONTEXT).await.expect("restore cancelled poll"));}

#[tokio::test]
async fn deferred_poll_consumes_one_permit_and_forces_captured_options(){let(lane,drive,faux)=fixture_with_options(maho_ai::providers::faux::RegisterFauxProviderOptions {deferred:Some(maho_ai::providers::faux::FauxDeferredOptions {pending_fetches:Some(1),poll_after_ms:None}),..Default::default()}).await;faux.set_responses(vec![answer().into()]);submit_deferred(&lane,&drive).await;assert_eq!(faux.state().deferred_fetch_count,0);let poll=poll_drive();let seen=Arc::new(Mutex::new(None));let captured=seen.clone();let _registration=lane.hooks.on(maho_agent::harness::hooks::HookName::BeforeRequest,Arc::new(move |event,_|{*captured.lock().expect("hook options lock")=Some(event.stream_options);Box::pin(async {Ok(maho_agent::harness::hooks::HookResult::None)})}),None);maho_agent::harness::runtime::drive::deferred::run_deferred(lane.as_ref(),&poll,&current(&lane)).await.expect("poll deferred");assert_eq!(*poll.deferred_permits.lock().expect("permit lock"),0);assert_eq!(seen.lock().expect("hook options lock").as_ref().expect("called hook").deferred,Some(maho_ai::types::DeferredOption::Enabled(false)));let OperationState::DeferredSuspended(s)=current(&lane) else {panic!("not suspended")};assert_eq!(s.deferred.poll,1);assert_eq!(faux.state().deferred_fetch_count,1);{let events=lane.events.lock().expect("events lock");assert_eq!(events.iter().rev().take(2).map(|e|e.event_type()).collect::<Vec<_>>(),vec!["run_suspend","turn_end"]);}assert!(matches!(maho_agent::harness::runtime::drive::deferred::run_deferred(lane.as_ref(),&poll,&current(&lane)).await.expect("no second poll"),ProcedureResult::Waiting {..}));assert_eq!(faux.state().deferred_fetch_count,1);assert_eq!(lane.state(),restore_lane(&lane.session,"main",&BACKGROUND_CONTEXT).await.expect("restore poll"));}
