async fn deferred_tools_use_poll_identity_and_reserved_id_timestamp(){let(lane,drive,faux)=fixture().await;let message=maho_ai::providers::faux::faux_assistant_message(maho_ai::providers::faux::faux_tool_call("lookup",Default::default(),Some("call")),maho_ai::providers::faux::FauxAssistantMessageOptions {stop_reason:Some(maho_ai::types::StopReason::ToolUse),..Default::default()});faux.set_responses(vec![message.into()]);submit_deferred(&lane,&drive).await;let OperationState::DeferredSuspended(before)=current(&lane) else {panic!("not suspended")};maho_agent::harness::runtime::drive::deferred::run_deferred(lane.as_ref(),&poll_drive(),&current(&lane)).await.expect("poll tools");let OperationState::Tools(s)=current(&lane) else {panic!("not tools")};assert_eq!(s.batch.turn_id,format!("{}:poll:1",before.deferred.step_id));assert_eq!(&s.batch.calls[0].result_entry_id()[..13],&s.operation.latest_assistant_entry_id.expect("assistant id")[..13]);assert_eq!(lane.state(),restore_lane(&lane.session,"main",&BACKGROUND_CONTEXT).await.expect("restore tools"));}
#[tokio::test]
async fn unknown_deferred_poll_replaces_ids_and_deletes_abandoned_frames(){let(lane,drive,faux)=fixture().await;faux.set_responses(vec![answer().into()]);submit_deferred(&lane,&drive).await;let unknown=unknown_poll(&lane).await;let OperationState::DeferredEffectPending(old)=&unknown else {unreachable!()};assert!(matches!(maho_agent::harness::runtime::drive::deferred::run_deferred(lane.as_ref(),&drive,&unknown).await.expect("wait unknown"),ProcedureResult::Waiting {..}));assert_eq!(lane.session.read_list(&pending_assistant_frames("op",&old.response_entry_id),None,&BACKGROUND_CONTEXT).await.expect("read old frames").len(),1);maho_agent::harness::runtime::drive::deferred::run_deferred(lane.as_ref(),&poll_drive(),&unknown).await.expect("recover poll");assert!(matches!(current(&lane),OperationState::Checkpoint(_)));assert!(lane.session.get_entry(&old.response_entry_id,&BACKGROUND_CONTEXT).await.expect("read old entry").is_none());assert!(lane.session.read_list(&pending_assistant_frames("op",&old.response_entry_id),None,&BACKGROUND_CONTEXT).await.expect("read deleted frames").is_empty());assert!(lane.events.lock().expect("events lock").iter().any(|e|e.recovery==Some(true)));assert_eq!(faux.state().deferred_fetch_count,1);}
