async fn unknown_deferred_poll_missing_model_keeps_permit_and_cleans_frames(){let(lane,drive,faux)=fixture().await;faux.set_responses(vec![answer().into()]);submit_deferred(&lane,&drive).await;let unknown=unknown_poll(&lane).await;let OperationState::DeferredEffectPending(old)=&unknown else {unreachable!()};lane.models.delete_provider("faux");let poll=poll_drive();assert!(matches!(maho_agent::harness::runtime::drive::deferred::run_deferred(lane.as_ref(),&poll,&unknown).await.expect("configuration failure"),ProcedureResult::Settled {..}));assert_eq!(*poll.deferred_permits.lock().expect("permit lock"),1);assert_eq!(faux.state().deferred_fetch_count,0);assert!(lane.state().operation.is_none());assert!(lane.session.read_list(&pending_assistant_frames("op",&old.response_entry_id),None,&BACKGROUND_CONTEXT).await.expect("deleted frames").is_empty());}

