async fn before_run_injected_messages_are_committed_and_published(){let(lane,drive,_)=fixture().await;let _registration=lane.hooks.on(maho_agent::harness::hooks::HookName::BeforeRun,Arc::new(|_,_|Box::pin(async {Ok(maho_agent::harness::hooks::HookResult::BeforeRun {messages:vec![maho_ai::types::Message::User(maho_ai::types::UserMessage {content:maho_ai::types::UserContent::Text("injected".into()),timestamp:2}).into()]})})),None);start_run(lane.as_ref(),&drive,&current(&lane)).await.expect("generation fixture must be valid");assert_eq!(lane.session.get_stats(&BACKGROUND_CONTEXT).await.expect("generation fixture must be valid").message_count,2);assert!(lane.events.lock().expect("generation fixture must be valid").iter().any(|event|event.event_type()=="entry_added"));let OperationState::Checkpoint(s)=current(&lane) else {panic!("not checkpoint")};assert_eq!(Some(s.checkpoint.trigger_entry_id),lane.state().tip_id);}
