async fn recovers_committed_frames_without_provider_or_response_hook(){let(lane,drive,_)=fixture().await;ready(&lane,&drive).await;let OperationState::AssistantReady(s)=current(&lane) else {panic!("not ready")};let pending=OperationState::AssistantEffectPending(AssistantEffectPendingOperation {operation:s.operation,assistant:s.assistant,attempt:1,response_entry_id:(lane.session.id_generator())(Some(1)),usage_id:(lane.session.id_generator())(Some(1)),intended_output_limit:100,context_window:1000,at:OperationMarker::AssistantEffectPending});let OperationState::AssistantEffectPending(effect)=&pending else {unreachable!()};let mut partial=answer();partial.stop_reason=maho_ai::types::StopReason::Pending;lane.session.append_list(&pending_assistant_frames("op",&effect.response_entry_id),serde_json::to_value(maho_ai::utils::assistant_message_frame::AssistantMessageFrame::Start {partial:Box::new(partial)}).expect("generation fixture must be valid"),&BACKGROUND_CONTEXT).await.expect("generation fixture must be valid");let mut projection=lane.state();projection.operation.as_mut().expect("generation fixture must be valid").state=pending.clone();lane.publish_state(projection);let count=Arc::new(std::sync::atomic::AtomicUsize::new(0));let captured=count.clone();let _registration=lane.hooks.on(maho_agent::harness::hooks::HookName::AfterResponse,Arc::new(move |_,_|{captured.fetch_add(1,std::sync::atomic::Ordering::SeqCst);Box::pin(async {Ok(maho_agent::harness::hooks::HookResult::None)})}),None);recover_assistant_generation(lane.as_ref(),&drive,&pending).await.expect("generation fixture must be valid");assert_eq!(count.load(std::sync::atomic::Ordering::SeqCst),0);let entry=lane.session.get_entry(&effect.response_entry_id,&BACKGROUND_CONTEXT).await.expect("generation fixture must be valid").expect("generation fixture must be valid");let Some(maho_ai::types::Message::Assistant(message))=entry.kind.message().and_then(|m|m.try_as_llm()) else {panic!("not assistant")};assert_eq!(message.content,answer().content);assert_eq!(message.usage,maho_ai::types::Usage::default());}
#[tokio::test]
async fn retries_live_provider_error_with_durable_wait_event(){let(lane,drive,_)=fixture().await;ready(&lane,&drive).await;let mut message=answer();message.stop_reason=maho_ai::types::StopReason::Error;message.error_message=Some("429 rate limit".into());response(&lane,&drive,message).await;let OperationState::AssistantRetryWait(s)=current(&lane) else {panic!("no retry")};assert_eq!(s.retry_wait.next_attempt,2);assert!(lane.events.lock().expect("generation fixture must be valid").iter().any(|e|e.event_type()=="retry_scheduled"));assert_eq!(lane.state(),restore_lane(&lane.session,"main",&BACKGROUND_CONTEXT).await.expect("generation fixture must be valid"));}
#[tokio::test]
async fn local_retry_wait_is_abort_aware(){let(lane,_,_)=fixture().await;let drive=Drive::new(&DriveOptions {operation_id:"op".into(),wait_for_retry:Some(true),poll_deferred:None},&BACKGROUND_CONTEXT);ready(&lane,&drive).await;let mut message=answer();message.stop_reason=maho_ai::types::StopReason::Error;message.error_message=Some("429 rate limit".into());response(&lane,&drive,message).await;let mut projection=lane.state();if let OperationState::AssistantRetryWait(s)=&mut projection.operation.as_mut().expect("generation fixture must be valid").state{s.retry_wait.not_before=i64::MAX;}lane.publish_state(projection);let cancellation=maho_agent::harness::execution::effect_gate::Cancellation::new();cancellation.resolve();drive.begin_abort(cancellation);drive.signal_abort();assert!(run_retry_wait(lane.as_ref(),&drive,&current(&lane)).await.is_err());assert!(matches!(current(&lane),OperationState::AssistantRetryWait(_)));}
